
const _defaultLogoDataUrl = "data:image/png;base64,";

// โลโก้ตรา กสทช. (ครุฑใหญ่ + "กสทช.") — ใช้เฉพาะใบนำฝากชำระเงิน (Bill Payment Slip)
// โลโก้อื่นๆ (ชส.01, ชส.02, หนังสือแจ้งความประสงค์) ยังใช้ _defaultLogoDataUrl (ครุฑเล็ก) เหมือนเดิม
const _nbtcSealLogoDataUrl = "data:image/png;base64,";

/** URL ของ Logo ที่ใช้งานอยู่ปัจจุบัน */
let customLogoDataUrl = _defaultLogoDataUrl;

/* ── จัดการ Logo ─────────────────────────────────────────────────────────── */

/**
 * อัปโหลด Logo ใหม่ (ไม่เกิน 2 MB)
 * @param {HTMLInputElement} input
 */
function handleLogoUpload(input) {
  if (!input.files?.[0]) return;
  const file = input.files[0];
  if (file.size > 2 * 1024 * 1024) {
    alert('ไฟล์ขนาดใหญ่เกิน 2 MB กรุณาเลือกไฟล์ใหม่');
    return;
  }
  const reader = new FileReader();
  reader.onload = e => {
    customLogoDataUrl = e.target.result;
    const preview  = document.getElementById('logo-preview');
    const resetBtn = document.getElementById('logo-reset-btn');
    if (preview)  { preview.src = customLogoDataUrl; preview.style.display = 'block'; }
    if (resetBtn) resetBtn.style.display = 'block';
    showToast('อัปโหลด Logo เรียบร้อยแล้ว ✓');
  };
  reader.readAsDataURL(file);
}

/** รีเซ็ต Logo กลับเป็นตราครุฑ default */
function resetLogo() {
  customLogoDataUrl = null;
  const preview  = document.getElementById('logo-preview');
  const resetBtn = document.getElementById('logo-reset-btn');
  const input    = document.getElementById('logo-upload-input');
  if (preview)  { preview.src = ''; preview.style.display = 'none'; }
  if (resetBtn) resetBtn.style.display = 'none';
  if (input)    input.value = '';
  showToast('กลับใช้ตราครุฑเรียบร้อยแล้ว');
}

