/* ══════════════════════════════════════════════════════════════════════
   ใบนำฝากชำระเงินค่าสินค้าและบริการ (Bill Payment Pay-IN Slip)
   รูปแบบตามฟอร์มธนาคาร (บมจ.ธนาคารกสิกรไทย / บมจ.ธนาคารไทยพาณิชย์)
   ══════════════════════════════════════════════════════════════════════ */

/** แปลงวันครบกำหนดชำระ (เก็บใน appState.dueDate เป็น DD/MM/YYYY พ.ศ. อยู่แล้ว)
 *  ให้แสดงผลตรงกับฟอร์ม ถ้ายังไม่มีค่าให้คืนช่องว่างเว้นบรรทัดให้กรอกมือ */
function _depositSlipDueDateText() {
  return appState.dueDate || '……………………';
}

/**
 * พิมพ์ "ใบนำฝากชำระเงินค่าสินค้าและบริการ (Bill Payment Pay-IN Slip)"
 * อ้างอิงจากฟอร์มต้นฉบับของธนาคาร (บมจ.ธนาคารกสิกรไทย COMP CODE 32313 /
 * บมจ.ธนาคารไทยพาณิชย์ เลขที่บัญชี 025-3-03036-7) ทุกจุด
 *
 * หมายเหตุสำคัญ: บาร์โค้ด/QR Code ท้ายฟอร์มในต้นฉบับเป็นบาร์โค้ดที่เข้ารหัส
 * ตามสเปกเฉพาะของธนาคาร (encode COMP CODE + Ref.1 + Ref.2 + จำนวนเงิน) ซึ่ง
 * ต้องใช้ไลบรารีสร้างบาร์โค้ด/QR จริงและทราบสเปกการเข้ารหัสที่ถูกต้องจากธนาคาร
 * — ฟังก์ชันนี้จึงแสดงเฉพาะตัวเลขอ้างอิง (Ref.1/Ref.2) เป็นตัวอักษรแทนบาร์โค้ด
 * ไปก่อน ถ้าต้องการบาร์โค้ด/QR ที่สแกนได้จริง แจ้งเพิ่มเติมได้
 */
/**
 * 🌟 [แก้ไข] ฝังโค้ดไลบรารี JsBarcode/qrcode-generator ไว้ในไฟล์นี้เลย (เข้ารหัส
 * base64 ไว้ ไม่ให้ปนกับโค้ดหลักของไฟล์) แทนการโหลดจาก CDN ตอนรันไทม์ ทำให้
 * ใช้งานได้แบบออฟไลน์ 100% และไม่มีปัญหา "บาร์โค้ด/QR ไม่ขึ้น" จากเน็ตหลุดอีก
 *
 * ที่มา: JsBarcode v3.12.3 (MIT License, © Johan Lindell)
 *        qrcode-generator (MIT License, © Kazuhiko Arase)
 */
const _JSBARCODE_LIB_B64 = "";
const _QRCODE_LIB_B64 = "";

/**
 * แทรกโค้ดไลบรารี (ที่ decode จาก base64 แล้ว) เข้าไปเป็น <script> ในหน้า
 * ปัจจุบัน ถ้ายังไม่มีตัวแปรโกลบอลของไลบรารีนั้นอยู่ก่อนแล้ว
 * @param {string} id - id ของ <script> (กันแทรกซ้ำ)
 * @param {string} b64 - เนื้อไฟล์ไลบรารีที่เข้ารหัส base64 ไว้
 * @param {string} globalName - ชื่อตัวแปรโกลบอลที่ไลบรารีนั้นควรสร้างขึ้น
 */
function _injectEmbeddedLib(id, b64, globalName) {
  if (typeof window[globalName] !== 'undefined') return;
  if (document.getElementById(id)) return;
  try {
    const code = decodeURIComponent(escape(atob(b64)));
    const s = document.createElement('script');
    s.id = id;
    s.textContent = code;
    document.head.appendChild(s);
  } catch (e) {
    console.error('[printDepositSlip] แทรกไลบรารี ' + id + ' ไม่สำเร็จ:', e);
  }
}

function _ensureBarcodeLibsLoaded() {
  _injectEmbeddedLib('lib-jsbarcode', _JSBARCODE_LIB_B64, 'JsBarcode');
  _injectEmbeddedLib('lib-qrcode', _QRCODE_LIB_B64, 'qrcode');
}

/**
 * แปลงเลขไทย (๐-๙) ในสตริงให้เป็นเลขอารบิก เผื่อ appState.year เก็บเป็นเลขไทย
 */
function _toArabicDigits(str) {
  const thaiDigits = '๐๑๒๓๔๕๖๗๘๙';
  return String(str || '').replace(/[๐-๙]/g, (d) => String(thaiDigits.indexOf(d)));
}

function printDepositSlip() {
  renderStep5AndSummary();

  // 🌟 [แก้ไข] แทรกโค้ดไลบรารีที่ฝังไว้เข้าหน้าเว็บ (ทำงานทันที ไม่ต้องรอโหลดจากเน็ต)
  _ensureBarcodeLibsLoaded();

  const licensee   = appState.licensee || '(ชื่อผู้รับใบอนุญาต)';
  const taxId      = appState.taxid || '';
  const refNo      = appState.refNo || '';
  const netAmount  = pv(document.getElementById('s5-net')?.value);
  const netAmountFmt = fmt(netAmount);
  const amountText = numberToThaiBahtText(netAmount);
  const dueDateText = _depositSlipDueDateText();

  // ══════════════════════════════════════════════════════════════════════
  // ระบบ CROSS BANK BILL PAYMENT ของไทย — อธิบายการทำงานและโครงสร้างข้อมูล
  // ══════════════════════════════════════════════════════════════════════
  //
  // ── ภาพรวมระบบ ─────────────────────────────────────────────────────
  // Bill Payment คือบริการที่ธนาคารหลายแห่งในไทยรองรับให้ลูกค้าชำระเงินให้
  // "ผู้รับชำระ" (Biller) ผ่านช่องทางของธนาคารอื่นได้ โดยไม่ต้องมีบัญชีกับ
  // ธนาคารเดียวกับผู้รับชำระ บริหารโดยสมาคมธนาคารไทย (TBA) ผ่าน BAHTNET
  //
  // ── ผู้เล่นหลักในระบบ ───────────────────────────────────────────────
  //  Biller       = ผู้รับเงิน เช่น กสทช. (สมัครกับธนาคารตัวแทน)
  //  Biller Bank  = ธนาคารที่ Biller สมัคร ในที่นี้คือ "ธนาคารกสิกรไทย"
  //  Paying Bank  = ธนาคารของผู้ชำระ (ธนาคารไหนก็ได้ที่รองรับ Bill Payment)
  //  Comp Code    = รหัส 5 หลักที่ TBA กำหนดให้ Biller แต่ละราย
  //                 ใช้แทนชื่อและบัญชีของ Biller ในระบบกลางธนาคาร
  //
  // ── โครงสร้างบาร์โค้ด Code 128 (ใช้ที่เคาน์เตอร์ธนาคาร) ─────────────
  //  รูปแบบ: [Comp Code 5] + [Ref.1 สูงสุด 15] + [Ref.2 สูงสุด 20] + [Amount x100 10]
  //  ตัวอย่าง: 32313 + 0123456789012 + 25670001 + 0000019260000
  //  รวม: 48 ตัวอักษร ตัวเลขล้วน ไม่มีช่องว่าง
  //
  //  พนักงานธนาคารสแกนบาร์โค้ด → host-to-host ตัดเงิน → ส่งข้อมูลให้ กสทช.
  //  ✅ บาร์โค้ดนี้ใช้งานได้จริงที่เคาน์เตอร์ถ้า Comp Code ถูกต้อง
  //
  // ── Ref.1 และ Ref.2 ─────────────────────────────────────────────────
  //  Ref.1 = เลขผู้เสียภาษี 13 หลักของผู้ประกอบการ (ผู้จ่ายเงิน)
  //          ธนาคารใช้ระบุตัวตนผู้ชำระ ส่งกลับมาให้ กสทช. ใน daily reconcile
  //
  //  Ref.2 = รหัสอ้างอิงธุรกรรม (ตัวเลขล้วน ≤20 หลัก)
  //          ในระบบนี้ใช้: เลขที่ ref_no (ตัดอักษรออก) + ปีบัญชี
  //          ตัวอย่าง: ref_no="NBTC2567001" → Ref.2="25670012567"
  //
  // ── QR Code มาตรฐาน (2 แบบ) ─────────────────────────────────────────
  //
  //  แบบที่ 1: ข้อมูลอ้างอิงดิบ (ที่โค้ดนี้สร้าง — ใช้งานได้บางส่วน)
  //    ข้อมูล: CompCode:XXXXX|Ref1:XXXXX|Ref2:XXXXX|Amount:XXXXX
  //    → แอปบางตัวอ่านและเติมฟอร์มได้ แต่ไม่ใช่ "สแกนแล้วจ่ายทันที"
  //
  //  แบบที่ 2: EMVCo Thai QR Bill Payment (มาตรฐานจริง — ยังไม่ implement)
  //    โครงสร้าง TLV (Tag-Length-Value) ตามมาตรฐาน BOT/EMV:
  //      Tag 00: "01"                    (Payload Format Indicator)
  //      Tag 01: "12"                    (Dynamic QR)
  //      Tag 29:                         (Merchant Account Info)
  //        Sub-tag 00: "A000000677010111" (Application ID ของ PromptPay/BillPay)
  //        Sub-tag 01: Biller ID          ← ต้องขอจาก KBANK (เช่น "0066666010001")
  //        Sub-tag 02: Ref.1
  //        Sub-tag 03: Ref.2
  //      Tag 52: "0000"                  (Merchant Category Code)
  //      Tag 53: "764"                   (Currency: THB)
  //      Tag 54: ยอดเงิน                 (Transaction Amount)
  //      Tag 58: "TH"                    (Country Code)
  //      Tag 63: CRC16/CCITT             (Checksum 4 หลัก)
  //
  //    ⚠️ EMVCo QR ต้องมี "Biller ID" ที่ KBANK ออกให้ กสทช. อย่างเป็น
  //       ทางการหลังจากสมัครบริการ Bill Payment — ถ้าไม่มีตัวเลขนี้ ไม่สามารถ
  //       สร้าง QR ที่ถูกต้องและสแกนจ่ายได้จริงในแอปธนาคาร
  //
  // ── สรุปสถานะโค้ดนี้ ────────────────────────────────────────────────
  //  ✅ Barcode Code128 — ใช้ที่เคาน์เตอร์ธนาคารได้ (ถ้า Comp Code ถูก)
  //  ✅ QR ข้อมูลอ้างอิง — บางแอปอ่านได้ ช่วยเติมข้อมูล
  //  ❌ EMVCo QR สแกนจ่ายได้ทันที — ต้องขอ Biller ID จาก KBANK ก่อน
  // ══════════════════════════════════════════════════════════════════════

  const compCode = '32313'; // COMP CODE ธนาคารกสิกรไทย — ยืนยันกับ กสทช./KBANK ก่อน production
  const fiscalYearDigits = _toArabicDigits(appState.year).replace(/\D/g, '');
  const ref1 = taxId;
  // 🌟 [แก้ไข] Ref.2 ต้องเป็นตัวเลขล้วน ห้ามมีตัวอักษรปน (เช่น "BK") — ตัด
  // ตัวอักษรทิ้งก่อนนำไปต่อกับปีบัญชี
  const ref2 = `${refNo.replace(/\D/g, '')}${fiscalYearDigits}`.slice(0, 20);
  const amountCents = String(Math.round(netAmount * 100)).padStart(10, '0');
  const barcodeContent = `${compCode}${ref1}${ref2}${amountCents}`;
  const qrContent = `CompCode:${compCode}|Ref1:${ref1}|Ref2:${ref2}|Amount:${netAmountFmt}`;

  let qrImgTag = '<div style="font-size:10px;color:#999;">[ไม่พบไลบรารี QR Code]</div>';
  if (typeof qrcode === 'function') {
    try {
      const qr = qrcode(0, 'M'); // typeNumber 0 = auto-detect ขนาดตามความยาวข้อมูล
      qr.addData(qrContent);
      qr.make();
      qrImgTag = qr.createImgTag(3, 4);
    } catch (e) {
      console.error('[printDepositSlip] สร้าง QR code ไม่สำเร็จ:', e);
    }
  }

  let barcodeImgTag = '<div style="font-size:10px;color:#999;">[ไม่พบไลบรารีบาร์โค้ด]</div>';
  if (typeof JsBarcode === 'function') {
    try {
      const canvas = document.createElement('canvas');
      // 🌟 [แก้ไข] "barcode เบลอ/มัว" เกิดจากแคนวาสมีความละเอียดต่ำ (width เดิม
      // 1.6 หรือ 1.1) แล้วถูก CSS ยืด (width:100%) ให้ใหญ่ขึ้นหลายเท่า ทำให้
      // ภาพขยาย (upscale) จนพร่ามัว — แก้โดยเรนเดอร์แคนวาสที่ความละเอียดสูงกว่า
      // เดิมมาก (width:3) แล้วให้ CSS แสดงผลในขนาดที่เล็กกว่าแคนวาสจริง (ย่อ/
      // downscale) ซึ่งจะได้เส้นที่คมชัดและดูบางลงไปในตัว โดยไม่ต้องแลกกับความคม
      JsBarcode(canvas, barcodeContent, {
        format: 'CODE128', width: 1.4, height: 60,
        displayValue: false, margin: 0, background: '#ffffff',
      });
      barcodeImgTag = `<img src="${canvas.toDataURL('image/png')}" alt="barcode"/>`;
    } catch (e) {
      console.error('[printDepositSlip] สร้างบาร์โค้ดไม่สำเร็จ:', e);
    }
  }

  // 🌟 [แก้ไข] ขยายขนาดโลโก้ กสทช. ให้ใหญ่ขึ้นกว่าเดิม (เดิม 40x46) ตามที่ขอในรูป
  // ── โลโก้ใบนำฝาก: ใช้ตรา กสทช. ใหญ่ (NBTC seal) เฉพาะหน้านี้ ──────────────
  // ถ้าผู้ใช้อัปโหลดโลโก้เองไว้ (customLogoDataUrl) ก็ใช้อันนั้นแทน
  // เอกสารอื่น (ชส.01/ชส.02) ยังใช้ _defaultLogoDataUrl (ครุฑเล็ก) เหมือนเดิม
  const logoHtml = `<img src="${customLogoDataUrl || _nbtcSealLogoDataUrl}" width="64" height="74" alt="logo" style="display:block;object-fit:contain;flex-shrink:0;"/>`;

  const bankGrid = [
    'ธ.กสิกรไทย', 'ธ.ทีเอ็มบีธนชาติ', 'ธ.ซีไอเอ็มบีไทย', 'ธ.ไอซีบีซี(ไทย)', 'ธ.เกียรตินาคิน',
    'ธ.ไทยพาณิชย์', 'ธ.ออมสิน', 'ธ.ยูโอบี', 'ธ.ซิตี้แบงก์ เอ็น.เอ.', 'ธ.กรุงไทย',
    'ธ.กรุงเทพ', 'ธ.มิซูโฮ', 'ธ.กรุงศรีอยุธยา', 'ธ.ทิสโก้',
  ];

  const css = `
    /* 🌟 [แก้ไข] บังคับให้เบราว์เซอร์พิมพ์สีพื้นหลัง/สีตัวอักษรออกมาตามจริง
       (ปัญหาเดิม "ปริ้นออกมาจริงๆ สีไม่ออกตาม" เกิดจากเบราว์เซอร์ปิดการพิมพ์
       สีพื้นหลังโดย default ต้องระบุ print-color-adjust:exact ให้ทุก element) */
    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; color-adjust: exact; }
    /* 🌟 [แก้ไข] เนื้อหา font-weight 200, ลดขนาดตัวอักษรพื้นฐานลงจาก 12.5px เป็น 11px */
    .ds-wrap { width:100%; font-family:'Sarabun',Arial,sans-serif; font-size:11px; color:#000; background:#fff; font-weight:200; }
    .ds-page { padding:14mm 12mm; }
    .ds-title-bar { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:10px; }
    .ds-title-box { border:2px solid #000; padding:6px 12px; font-weight:700; font-size:12.5px; }
    .ds-title-right { text-align:right; font-size:10.5px; }
    .ds-header-row { display:flex; justify-content:space-between; gap:16px; margin-bottom:10px; }
    .ds-org { display:flex; gap:10px; align-items:flex-start; }
    .ds-org-text { font-size:10.5px; line-height:1.6; }
    .ds-org-text .ds-org-title { font-weight:700; font-size:12px; }
    .ds-info-table { border-collapse:collapse; min-width:280px; }
    .ds-info-table td { border:1px solid #000; padding:4px 8px; font-size:10.5px; }
    .ds-info-table .ds-info-hd { background:#dbe9f7; font-weight:700; text-align:center; }
    .ds-info-table .ds-info-label { background:#eaf3fb; white-space:nowrap; }
    .ds-info-table .ds-info-val { min-width:150px; }
    .ds-branch-line { text-align:right; font-size:10.5px; margin-bottom:8px; }
    .ds-account-line { display:flex; align-items:center; gap:8px; margin:4px 0; font-size:11px; }
    .ds-box { width:13px; height:13px; border:1.4px solid #000; display:inline-block; flex-shrink:0; }
    .ds-deadline { color:#c62828; font-size:10.5px; text-align:right; line-height:1.6; }
    .ds-main-table { border-collapse:collapse; width:100%; margin-top:10px; font-size:10.5px; }
    .ds-main-table td { border:1px solid #000; padding:5px 8px; vertical-align:middle; }
    .ds-main-table .ds-hd { background:#dbe9f7; font-weight:700; }
    .ds-amount-words { background:#dbe9f7; font-weight:700; white-space:nowrap; }
    .ds-footer-row { display:flex; justify-content:space-between; margin-top:10px; font-size:10.5px; }
    .ds-bank-use { border:1px solid #000; }
    .ds-bank-use-hd { background:#dbe9f7; font-weight:700; padding:4px 8px; border-bottom:1px solid #000; }
    .ds-bank-use-body { padding:6px 8px; }
    .ds-note-line { text-align:center; font-size:10.5px; margin:12px 0 8px; }
    /* 🌟 [แก้ไข] จัดวางใหม่: แถวบนเป็นกล่องรายชื่อธนาคาร (ซ้าย) คู่กับ QR code
       เล็กๆ (ขวา) วางเคียงกัน ส่วนบาร์โค้ดแยกเป็นแถบเต็มความกว้างด้านล่างสุด */
    .ds-bank-grid-wrap { display:flex; gap:16px; align-items:flex-start; }
    .ds-bank-grid { flex:1; border:1px solid #ccc; border-radius:6px; padding:8px 10px; }
    .ds-bank-grid table { width:100%; border-collapse:collapse; }
    .ds-bank-grid td { font-size:10px; padding:4px 8px; white-space:nowrap; }
    .ds-qr-box { flex-shrink:0; width:80px; text-align:center; }
    .ds-qr-box img { width:100%; height:auto; }
    /* 🌟 [แก้ไข] จำกัดความกว้างบาร์โค้ดให้ไม่เกินกล่องรายชื่อธนาคาร (แทนที่จะ
       เต็มหน้ากระดาษ) โดยจัดให้อยู่กึ่งกลางแถว */
    .ds-barcode-wrap { margin-top:14px; text-align:center; max-width:calc(70% - 96px); margin-left:auto; margin-right:auto; }
    .ds-barcode-wrap img { width:auto; max-width:100%; height:42px; }
    .ds-ref-mono { font-family:monospace; font-size:10px; letter-spacing:1px; margin-top:6px; word-break:break-all; color:#555; }
  `;

  const html = `
    <style>${css}</style>
    <div class="ds-wrap">
      <div class="ds-page">

        <div class="ds-title-bar">
          <div class="ds-title-box">ใบนำฝากชำระเงินค่าสินค้าและบริการ (Bill Payment Pay-IN Slip)</div>
          <div class="ds-title-right">
            สำหรับลูกค้า / For Customer<br>
            โปรดเรียกเก็บค่านำส่งเงินรายปีจากผู้ชำระเงิน *
          </div>
        </div>

        <div class="ds-header-row">
          <div class="ds-org">
            ${logoHtml}
            <div class="ds-org-text">
              <div class="ds-org-title">สำนักงาน กสทช.</div>
              ที่อยู่ 87 ถนนพหลโยธิน ซอย 8 (สายลม)<br>
              แขวงสามเสนใน เขตพญาไท กรุงเทพฯ 10400<br>
              เลขประจำตัวผู้เสียภาษี 0994000049447<br>
              โทร. 02-271-7600
            </div>
          </div>
          <div>
            <div class="ds-branch-line">สาขา/Branch ………………………………………วันที่/Date ………………</div>
            <table class="ds-info-table">
              <tr><td class="ds-info-hd" colspan="2">ค่านำส่งเงินรายปีเข้ากองทุนวิจัยและพัฒนา</td></tr>
              <tr><td class="ds-info-label">ชื่อ/Name</td><td class="ds-info-val">${licensee}</td></tr>
              <tr><td class="ds-info-label">รหัสลูกค้า/Customer&nbsp;No.&nbsp;(Ref.1)</td><td class="ds-info-val">${taxId}</td></tr>
              <tr><td class="ds-info-label">หมายเลขอ้างอิง/Reference&nbsp;No.(Ref&nbsp;2)</td><td class="ds-info-val">${refNo}</td></tr>
            </table>
          </div>
        </div>

        <div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:6px;">
          <div>
            เพื่อเข้าบัญชี กองทุนบริการกิจการกระจายเสียงกิจการโทรทัศน์อย่างทั่วถึง<br>
            <div class="ds-account-line"><span class="ds-box"></span> บมจ.ธนาคารกสิกรไทย COMP CODE : 32313</div>
            <div class="ds-account-line"><span class="ds-box"></span> บมจ.ธนาคารไทยพาณิชย์ เลขที่บัญชี 025-3-03036-7 (Bill Payment)</div>
          </div>
          <div class="ds-deadline">
            สามารถชำระเงินได้ ภายในวันที่ ${dueDateText} เวลา 23.00 น.<br>
            ** หากไม่ชำระค่าดำเนินการให้ถูกต้องและครบถ้วน ภายในระยะเวลาที่กำหนด<br>
            จะไม่สามารถชำระเงินได้
          </div>
        </div>

        <table class="ds-main-table">
          <tr>
            <td class="ds-hd" style="width:15%;"><span class="ds-box" style="width:11px;height:11px;"></span> เช็ค/Cheque</td>
            <td class="ds-hd" style="width:15%;"><span class="ds-box" style="width:11px;height:11px;"></span> เงินสด/Cash</td>
            <td class="ds-hd" colspan="2">จำนวนเงิน / Amount --&gt;</td>
          </tr>
          <tr>
            <td colspan="2"></td>
            <td class="ds-hd">หมายเลขเช็ค / Cheque No</td>
            <td class="ds-hd">จำนวนเงิน (บาท)/Amount (Baht)</td>
          </tr>
          <tr>
            <td colspan="2"></td>
            <td>&nbsp;</td>
            <td style="text-align:right;font-weight:700;">${netAmountFmt}</td>
          </tr>
          <tr>
            <td class="ds-amount-words" colspan="2">จำนวนเงินเป็นตัวอักษร / Amount in Words</td>
            <td colspan="2">${amountText}</td>
          </tr>
        </table>

        <div class="ds-footer-row">
          <div style="line-height:2.1;">
            ผู้นำฝาก/Deposit by …………………………………………………<br>
            โทรศัพท์/Telephone …………………………………………………
          </div>
          <div class="ds-bank-use" style="min-width:260px;">
            <div class="ds-bank-use-hd">สำหรับเจ้าหน้าที่ธนาคาร / For Bank's Use</div>
            <div class="ds-bank-use-body">ผู้รับเงิน...............................................................</div>
          </div>
        </div>

        <div class="ds-note-line">
          โปรดนำใบฝากนี้ไปชำระเงินได้ที่ บมจ.ธนาคารกสิกรไทย หรือ บริการชำระบิลข้ามธนาคาร ผ่านช่องทางอิเล็กทรอนิกส์
        </div>

        <div class="ds-bank-grid-wrap">
          <div class="ds-bank-grid">
            <table>
              <tr>${bankGrid.slice(0, 5).map(b => `<td>${b}</td>`).join('')}</tr>
              <tr>${bankGrid.slice(5, 10).map(b => `<td>${b}</td>`).join('')}</tr>
              <tr>${bankGrid.slice(10, 14).map(b => `<td>${b}</td>`).join('')}</tr>
            </table>
          </div>
          <div class="ds-qr-box">
            ${qrImgTag}
          </div>
        </div>

        <div class="ds-barcode-wrap">
          ${barcodeImgTag}
          <div class="ds-ref-mono">${compCode} ${ref1} ${ref2} ${amountCents}</div>
        </div>

      </div>
    </div>`;

  const filename = `ใบนำฝากชำระเงิน_${(appState.licensee || 'กสทช').replace(/\s+/g, '_')}`;
  _openPrintWindow(html, filename);
  showToast('กำลังเปิดหน้าต่างพิมพ์ใบนำฝากชำระเงิน');
}